async function plLeave(c,camp){c.campaigns=c.campaigns.filter(x=>x!==camp);const id=plJoinKey(camp,c.id);PL.roster=PL.roster.filter(x=>x.id!==id);if(VIEW.tdb)await dbWrite('tavolo/players/roster/'+id,{json:JSON.stringify({id,campaign:camp,owner:PL.account,joined:false,at:Date.now()})});plStoreRoster()}
function plValidateImport(v){const c=v.character;if(v.version!==1||!c||!plClass(c)||!plSub(c)||!Array.isArray(c.traits)||c.traits.length!==6||!c.traits.every(Number.isFinite)||!Number.isInteger(c.level)||c.level<1||c.level>10||!Array.isArray(c.cards)||c.cards.some(x=>!plCard(x.i)||plCard(x.i).c!=='d')||new Set(c.cards.map(x=>x.i)).size!==c.cards.length||!Array.isArray(c.experiences)||!Array.isArray(c.subcards))throw Error('Il file non è un backup personaggio valido.');if(plCard(c.ancestry)?.c!=='a'||plCard(c.community)?.c!=='c'||c.subcards.some(i=>plCard(i)?.c!=='s')||c.experiences.some(x=>typeof x.name!=='string'||!Number.isFinite(x.value))||typeof c.name!=='string'||!Number.isFinite(c.proficiency))throw Error('Campi del backup non validi.');if(c.multiclass){const k=PLAYER_RULES.classes[c.multiclass.className];if(!k||!k.domains.includes(c.multiclass.domain)||!k.subclasses.some(x=>x.name===c.multiclass.subclass))throw Error('Multiclass non valido.');}if(c.items!==undefined&&(!Array.isArray(c.items)||c.items.some(x=>!eqItem(x.gear)||typeof x.uid!=='string'||!Number.isInteger(x.qty)||x.qty<1||x.qty>99||eqItem(x.gear).kind==='consumable'&&x.qty>5)))throw Error('Inventario del backup non valido.');const clean=plNew(),allowed=new Set([...Object.keys(clean),'multiclass','companionData','conditions','spellTrait','classResourceNotes','gmAt','items','equipmentState','equipmentMigrated','inventoryWeaponSlots','inventoryCardsMigrated','outgoingTrades','receivedTrades',...Array.from({length:2},(_,i)=>['Name','Trait','Damage','Feature','Type'].map(x=>'inventoryWeapon'+i+x)).flat()]);for(const [key,value]of Object.entries(plClone(c)))if(allowed.has(key))clean[key]=value;clean.id=plId();clean.campaigns=[];clean.updated=Date.now();plClampTracks(clean);if(plActive(clean).length>eqLoadoutMax(clean))throw Error('Il backup supera le 5 carte attive.');return clean}
let plFilterTimer;
document.addEventListener('click',e=>{if(e.target.matches?.('[data-pl-overlay]')){e.stopImmediatePropagation();plAction('close-modal',{});return}const b=e.target.closest?.('[data-pl]');if(!b)return;e.preventDefault();e.stopImmediatePropagation();Promise.resolve(plAction(b.dataset.pl,b.dataset)).catch(err=>{PL.error=err.message;toast(err.message);plRender()})},true);
document.addEventListener('change',async e=>{const el=e.target;if(el.id==='pl-import'){try{const file=el.files?.[0];if(!file)return;if(file.size>2e6)throw Error('Backup troppo grande.');const c=plValidateImport(JSON.parse(await file.text()));PL.chars.push(c);PL.id=c.id;plSave(c);plRender()}catch(err){toast(err.message)}return}if(el.dataset.plRollCount){const c=plCurrent(),st=plProfileState(c,Number(el.dataset.plRollCount));st.rollCount=clamp(Math.trunc(Number(el.value))||1,1,50);plSave(c);return}if(el.dataset.plCardReset){const c=plCurrent();(c.cardState[el.dataset.plCardReset]||={}).reset=el.value;plSave(c);return}if(el.dataset.plMulti){const p=PL.level.pending;p[el.dataset.plMulti]=el.value;if(el.dataset.plMulti==='className'){p.subclass='';p.domain=''}plRender();return}if(el.dataset.plRestMove){PL.rest.moves[+el.dataset.plRestMove]=el.value;return}if(el.dataset.plFilter){PL[el.dataset.plFilter]=el.value;plRender();return}if(!el.dataset.plField)return;const w=el.dataset.plDraft?(PL.level?.work||PL.draft):plCurrent();if(!w)return;let v=el.value;const key=el.dataset.plField;if(el.type==='number'||el.tagName==='SELECT'&&(/^traits\./.test(key)||['ancestry','mixed','community','transformation'].includes(key)&&v!==''))v=Number(v);if(typeof v==='number'&&!Number.isFinite(v)){toast('Inserisci un valore valido.');return}if(key==='conditionsText')w.conditions=String(v).split(',').map(x=>x.trim()).filter(Boolean);else plSet(w,key,v);if(key==='primary'&&(plEquip(v)?.hands===2||plEquip(v)?.brawler))w.secondary='';if(!el.dataset.plDraft){if(key.startsWith('traits.'))plSet(w,key,clamp(Number(v),-3,10));if(['hpBonus','stressBonus','evasionBonus','armorBonus','majorBonus','severeBonus'].includes(key))plSet(w,key,clamp(Number(v),-5,20));if(key==='counters.focus')w.counters.focus=clamp(Number(v),0,6);if(key==='gold')w.gold=clamp(Number(v),0,99999);plClampTracks(w);plSave(w)}else if(!PL.level)plSave();plRender()},true);
document.addEventListener('input',e=>{const el=e.target;if(el.dataset.plFilter==='query'){PL.query=el.value;clearTimeout(plFilterTimer);plFilterTimer=setTimeout(()=>{const caret=el.selectionStart;plRender();const n=document.querySelector('[data-pl-filter="query"]');n?.focus();n?.setSelectionRange(caret,caret)},250);return}if(!el.dataset.plField||el.tagName==='SELECT'||el.type==='number')return;const w=el.dataset.plDraft?(PL.level?.work||PL.draft):plCurrent();if(w){plSet(w,el.dataset.plField,el.value);if(!PL.level)plSave(el.dataset.plDraft?null:w)}},true);
document.addEventListener('keydown',e=>{if(CV.open!=null||!PL.modal)return;if(e.key==='Escape'){e.preventDefault();e.stopImmediatePropagation();plAction('close-modal',{});return}if(e.key==='Tab'){const els=[...document.querySelectorAll('.pl-dialog button,.pl-dialog input,.pl-dialog select,.pl-dialog textarea,.pl-dialog summary')].filter(x=>!x.disabled&&x.getClientRects().length),first=els[0],last=els.at(-1);if(e.shiftKey&&(document.activeElement===first||document.activeElement.matches('.pl-dialog'))){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}},true);
addEventListener('storage',e=>{if(e.key===PL_DIR){try{PL.directory=JSON.parse(e.newValue)||[];plRenderIfVisible()}catch(x){}}if(e.key===PL_ROSTER){try{PL.roster=JSON.parse(e.newValue)||[];if(plReceiveRoster())persist();plRenderIfVisible()}catch(x){}}if(e.key===PL_KEY+':'+PL.account){try{plMerge(JSON.parse(e.newValue));plRenderIfVisible()}catch(x){}}if(e.key?.startsWith('dh-gm-status:')){const c=PL.chars.find(c=>c.campaigns.some(camp=>e.key==='dh-gm-status:'+plJoinKey(camp,c.id)));if(c){const m=JSON.parse(e.newValue);Object.assign(c,{hp:m.hp,stress:m.stress,hope:m.hope,armor:m.armor,conditions:m.conditions});plSave(c);plRenderIfVisible()}}});
plLoad();try{PL.directory=JSON.parse(localStorage.getItem(PL_DIR)||'[]');PL.roster=JSON.parse(localStorage.getItem(PL_ROSTER)||'[]')}catch(e){}
